#include <bits/stdc++.h>
#define fi first
#define se second
using namespace std;

const int MAXN = 5500;
const long long INF = 1e9 + 7;

int n, m, k, c, d;
int u, v, totalFlow = 0, s = MAXN - 2, t = MAXN - 1, parent[MAXN];
long long totalCost = 0, dist[MAXN];
priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

struct Edge {
    int v, c;
    int index, cap;
};
vector<Edge> adj[MAXN];

void addEdge(int u, int v, int cost, int capacity) {
    int szU = adj[u].size(), szV = adj[v].size();
    adj[u].push_back({v, cost, szV, capacity});
    adj[v].push_back({u, -cost, szU, 0});
}

void findShortest() {
    fill(dist, dist + MAXN, INF);
    pq.push({dist[s] = 0, s});
    while (!pq.empty()) {
        auto [currDist, u] = pq.top(); pq.pop();
        if (currDist > dist[u]) continue;
        for (auto &e : adj[u]) {
            if (e.cap > 0 && dist[e.v] > currDist + e.c) {
                parent[e.v] = e.index;
                dist[e.v] = currDist + e.c;
                pq.push({dist[e.v], e.v});
            }
        }
    }
}

void updateFlow() {
    int flowAdd = k, v = t;
    while (v != s) {
        int u = adj[v][parent[v]].v;
        int ind = adj[v][parent[v]].index;
        flowAdd = min(flowAdd, adj[u][ind].cap);
        v = u;
    }
    totalFlow += flowAdd;
    totalCost += (long long)flowAdd * dist[t];
    v = t;
    while (v != s) {
        int u = adj[v][parent[v]].v;
        int ind = adj[v][parent[v]].index;
        adj[v][parent[v]].cap += flowAdd;
        adj[u][ind].cap -= flowAdd;
        v = u;
    }
}

int nodeID(int u, int t) {
    return u + t * n;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        cin >> u;
        addEdge(s, nodeID(u, 0), 0, 1);
    }
    for (int i = 0; i <= n + k; i++)
        addEdge(nodeID(1, i), t, c * i, k);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < n + k; j++)
            addEdge(nodeID(i, j), nodeID(i, j + 1), 0, k);
    for (int i = 0; i < m; i++) {
        cin >> u >> v;
        for (int j = 0; j < k; j++) {
            for (int l = 0; l < n + k; l++) {
                addEdge(nodeID(u, l), nodeID(v, l + 1), d * (2 * j + 1), 1);
                addEdge(nodeID(v, l), nodeID(u, l + 1), d * (2 * j + 1), 1);
            }
        }
    }
    while (totalFlow < k) {
        findShortest();
        updateFlow();
    }
    cout << totalCost;
}
